import { Component, For, onMount, ParentComponent, Show } from "solid-js";

import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { useImageCache } from "#core/ui-next/components/image-cache.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel, PanelProps } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

import { SyncretismPreviewCard } from "#base/ui/syncretism/syncretism-card.jsx";

import style from "./screen-syncretism.scss?url";
import { SyncretismScreenModel, SyncretismScreenModelContext } from "./syncretism-screen-model.js";

const SyncretismInfoScreen: ParentComponent<PanelProps> = (props) => {
	const model = SyncretismScreenModel.get();

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<div class={"size-full flex flex-col flex-auto px-3 py-3"}>
				<FiligreeTitle.Accent
					text={props.name}
					textClass="text-xl"
					class="mb-4 mt-4 p-2 pointer-events-none"
				/>
				<div class="flex flex-row w-full mt-2 pb-4 pt-2 px-2">
					<AttentionBanner syncreticChoiceMade={model.syncretismChoiceMade} />
				</div>
				<ScrollArea
					class="relative flex-auto"
					useProxy={true}
				>
					<SpatialSlot
						name="syncretism-choices"
						class={`flex flex-auto flex-wrap size-full ${model.isSmallScreen() ? "justify-center" : ""}`}
					>
						<For each={model.data}>
							{(item) => (
								<SyncretismPreviewCard
									{...item}
									style={
										model.isSmallScreen()
											? { width: "95%" }
											: {
													width: "31.5%",
													"margin-left": "0.75%",
													"margin-right": "0.75%",
												}
									}
									class={`${model.isSmallScreen() ? "mb-10 mr-5" : "mb-5"} mt-3`}
								/>
							)}
						</For>
					</SpatialSlot>
				</ScrollArea>
			</div>
		</NestedTooltipContext.Provider>
	);
};

export interface SyncretismScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const SyncretismInfoComponent: Component<SyncretismScreenProps> = (props) => {
	const model = SyncretismScreenModel.get();
	const audio = useAudio("SyncretismPreview");

	onMount(() => {
		audio("popup-open");
	});

	return (
		<Panel
			ref={props.ref}
			name="Syncretism Preview Screen"
			id="syncretism-preview"
			class="syncretism-frame"
			onCancelInput={() => {
				model.clickCloseInfoButton();
				audio("popup-back");
			}}
		>
			<SyncretismScreenModelContext.Provider value={model}>
				<div class="inset-1 absolute bg-cover bg-no-repeat syncretism-bg-gradient" />
				<div class="relative flex flex-auto">
					<Tab class="w-full relative flex flex-col flex-auto pointer-events-auto">
						<CloseButton
							class={`${IsControllerActive() ? "hidden" : ""} absolute right-1\\.5 top-2`}
							onActivate={() => {
								model.clickCloseInfoButton();
								audio("popup-close");
							}}
						/>
						<Tab.Output />

						<Tab.Item
							name="syncretism-preview"
							title={() => "Syncretism Preview"}
							body={() => (
								<SyncretismInfoScreen
									ref={props.ref}
									name="LOC_UI_SYNCRETISM_PREVIEW_TITLE"
									id="syncretism-info-card"
								/>
							)}
						/>
					</Tab>
				</div>
			</SyncretismScreenModelContext.Provider>
		</Panel>
	);
};

interface AttentionBannerProps {
	syncreticChoiceMade: boolean;
}

const AttentionBannerSymbol = Symbol();
const AttentionBanner: Component<AttentionBannerProps> = (props) => {
	const images = {
		positiveBannerBaseCSS: "url(blp:positive_banner_base)",
		warningBannerBaseCSS: "url(blp:warning_banner_base)",
		warningBannerImageCSS: "url(blp:warning_banner_image)",
		playerDetailCSS: "url(blp:mp_player_detail)",
		iconWarningCSS: "url(blp:buildicon_warning)",
		iconPositiveCSS: "url(blp:icon_policy_assigned)",
	};

	const cache = useImageCache();
	cache.registerImages(AttentionBannerSymbol, Object.values(images));

	return (
		<div
			class="flex flex-auto mx-12 p-4 my-2 relative"
			style={{
				"border-image-source": `${props.syncreticChoiceMade ? images.positiveBannerBaseCSS : images.warningBannerBaseCSS}`,
				"border-image-slice": "22 180 fill",
				"border-image-width": "22px 180px",
			}}
		>
			<div
				class="bg-center bg-no-repeat absolute inset-0 bg-cover opacity-20"
				style={{ "background-image": images.warningBannerImageCSS }}
			/>
			<div
				class="absolute top-1 left-1 rotate-180 size-4 bg-contain opacity-30"
				style={{ "background-image": images.playerDetailCSS }}
			/>
			<div
				class="absolute top-1 right-1 -rotate-90 size-4 bg-contain opacity-30"
				style={{ "background-image": images.playerDetailCSS }}
			/>
			<div
				class="absolute bottom-1 left-1 rotate-90 size-4 bg-contain opacity-30"
				style={{ "background-image": images.playerDetailCSS }}
			/>
			<div
				class="absolute bottom-1 right-1 size-4 bg-center opacity-30"
				style={{ "background-image": images.playerDetailCSS }}
			/>
			<div class="flex flex-row flex-auto">
				<Icon
					class="size-12"
					name={`${props.syncreticChoiceMade ? images.iconPositiveCSS : images.iconWarningCSS}`}
					isUrl={true}
				/>

				<div class="flex flex-col flex-auto relative items-start justify-center ml-3">
					<Show
						when={!props.syncreticChoiceMade}
						fallback={<L10n.Stylize text={"LOC_UI_SYNCRETISM_POSTVIEW"} />}
					>
						<div class="text-accent-2">
							<L10n.Stylize text="LOC_UI_SYNCRETISM_PREVIEW" />
						</div>
						<div class="uppercase mr-2 text-secondary font-title">
							<L10n.Stylize text="LOC_UI_SYNCRETISM_PREVIEW_ONLY" />
						</div>
					</Show>
				</div>
			</div>
		</div>
	);
};

defineLegacyComponent(
	"syncretism-info-card",
	{
		classNames: ["syncretism-info-card"],
		tabIndex: -0,
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <SyncretismInfoCard />;
	},
);

export const SyncretismInfoCard = ComponentRegistry.register({
	name: "SyncretismInfo",
	styles: [style],
	createInstance: SyncretismInfoComponent,
});
